example.code:
#include <iostream>
#include <vector>

int main() {
    std::vector<int> v;
    for (int i = 1; i <= 9; ++i) {
        v.push_back(i);
        std::cout << v.size() << ' ' << v.capacity() << '\n';
    }
    std::cout << "sizeof: " << sizeof(v) << '\n';
    std::vector<int> b = v;
    b[0] = 99;
    std::cout << "v[0] b[0]: " << v[0] << ' ' << b[0] << '\n';
    v.clear();
    std::cout << "after clear: " << v.size() << ' ' << v.capacity() << '\n';
    v.shrink_to_fit();
    std::cout << "after shrink: " << v.size() << ' ' << v.capacity() << '\n';
    return 0;
}

