#include <iostream>
#include <vector>

int main() {
    std::vector<int> v;
    v.reserve(4);
    for (int i = 1; i <= 10; ++i) {
        v.push_back(i);
        std::cout << v.size() << ' ' << v.capacity() << '\n';
    }
    std::vector<int> backup = v;
    v.clear();
    std::cout << "after clear: " << v.size() << ' ' << v.capacity() << '\n';
    std::cout << "backup: " << backup.size() << '\n';
    v.shrink_to_fit();
    std::cout << "after shrink: " << v.size() << ' ' << v.capacity() << '\n';
    return 0;
}
